    ($SATQ$055aafe7$SATQ$, $SATQ$e2fa4379-f216-4286-8c00-6098b985ceea$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Geometry and Trigonometry$SATQ$, $SATQ$S$SATQ$, $SATQ$S.B.$SATQ$, $SATQ$Lines, angles, and triangles$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, NULL, $SATQ$<p style="text-align: left;">Triangle <math alttext="upper A upper B upper C"><mrow>
	<mi>A</mi>
	<mi>B</mi>
	<mi>C</mi>
</mrow>
